function localAnswer(q){
 const s=F.summary(state),f=F.forecast(state,15),p=F.price(state),n=q.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');let a;
 if(/prec|cobr|servic|margem|peca/.test(n))a=p.error?p.error:'Seu preço sugerido para “'+state.calc.name+'” é '+money(p.suggested)+'. O mínimo para cobrir os custos informados é '+money(p.floor)+'.\n\nSua estrutura e equipe somam '+money(p.monthly)+' por mês, divididos por '+dec(p.cap)+' horas produtivas. Por isso '+money(p.allocated)+' do custo deste serviço não está na peça.\n\nAo cobrar '+money(state.calc.current)+', a sobra estimada é '+money(p.netCurrent)+'. Reveja os custos e valide o preço com seu cliente.';
 else if(/gast|despes|econom|reduz/.test(n)){
 const costs={};state.records.filter(r=>r.kind==='out'&&r.status==='paid'&&F.paidDate(r)>=F.date(-29)&&F.paidDate(r)<=F.date()).forEach(r=>costs[r.cat]=(costs[r.cat]||0)+r.amount);const top=Object.entries(costs).sort((a,b)=>b[1]-a[1])[0];
 a=top?'Seu maior grupo de saídas pagas em 30 dias é '+top[0]+': '+money(top[1])+'.\n\nRevisar fornecedores, desperdício e compras antes de cortar algo essencial pode ajudar. Uma redução hipotética de 5% nessa categoria seria '+money(top[1]*.05)+' no período. Isso é simulação, não economia confirmada.':'Ainda não há despesas pagas para analisar. Registre os gastos em Meu caixa; os custos da calculadora são um planejamento separado.';
 }else if(/lucr|ganh|fatur|result|melhor|pior/.test(n))a='Em 30 dias, você recebeu '+money(s.income)+' e pagou '+money(s.expense)+'. O resultado de caixa foi '+money(s.result)+'. Isso não equivale necessariamente ao lucro contábil.\n\nNão há histórico suficiente e comparável para afirmar uma tendência ou prever novas vendas. Em 15 dias, considerando só os compromissos cadastrados, o saldo termina em '+money(f.balance)+'.';
 else if(/negoci|descont/.test(n))a=p.error?p.error:'Seu preço sugerido é '+money(p.suggested)+' e o piso estimado é '+money(p.floor)+'. Um desconto abaixo desse piso deixa de cobrir os custos informados.\n\nVocê pode oferecer outra forma de pagamento, reduzir o escopo ou pedir uma entrada. Se mudar a taxa do cartão ou o material, recalcule antes de fechar.';
 else if(/caixa|pag|bolet|conta|futur|prev|dinheiro|reserv|saldo/.test(n))a='Hoje há '+money(s.balance)+' disponíveis. Nos próximos 15 dias estão previstos '+money(f.receivable)+' a receber e '+money(f.payable)+' a pagar.\n\n'+(f.first?'O primeiro saldo negativo aparece em '+dateLabel(f.first)+'. O menor saldo é '+money(f.min)+'. Antecipe um recebimento ou negocie a data da conta antes de assumir novos gastos.':'Com os dados atuais, não há saldo negativo no período. Novos gastos e atrasos podem mudar isso.')+'\n\nA previsão usa os vencimentos cadastrados e não garante pagamento dos clientes na data. Use o cenário conservador para testar atrasos.';
 else a='Posso interpretar os dados cadastrados de caixa, preço, gastos e negociação.\n\nO saldo atual é '+money(s.balance)+'. '+(f.first?'Há risco de faltar dinheiro em '+dateLabel(f.first)+'.':'As contas previstas cabem no caixa no cenário cadastrado.')+'\n\nExperimente “Quanto cobrar pelo serviço?” ou “Vou ter dinheiro para pagar?”. Para perguntas abertas, configure um servidor de IA em Meu negócio.';
 return a;
}
