function closeModal(){$('#modal-root').innerHTML='';}
function modal(h,body,submitLabel='Salvar',formId='modal-form'){
 $('#modal-root').innerHTML='<div class="modalback"><section class="modal" role="dialog" aria-modal="true" aria-label="'+esc(h)+'"><div class="modalhead"><h2>'+h+'</h2><button class="iconbtn" data-action="close" aria-label="Fechar">'+icon('close')+'</button></div><form id="'+formId+'"><div class="formerror" role="alert"></div>'+body+'<div class="modalfoot"><button type="button" class="btn ghost" data-action="close">Cancelar</button><button type="submit" class="btn">'+submitLabel+'</button></div></form></section></div>';
 setTimeout(()=>$('#modal-root input')?.focus(),50);
}
function confirmAction(h,p,callback,label='Confirmar'){modal(h,'<p style="font-size:14px">'+p+'</p>',label,'confirm-form');$('#confirm-form').onsubmit=e=>{e.preventDefault();callback();closeModal();render();};}
function formError(e){const error=$('.formerror');if(error){error.textContent=e.message;error.style.display='block';}else toast(e.message);}
function numeric(data,k,max=1e9){const raw=data.get(k);if(raw===null||String(raw).trim()==='')throw Error('Preencha todos os valores. Use 0 quando não houver custo.');const n=F.number(raw);if(!Number.isFinite(n)||n<0||n>max)throw Error('Informe valores válidos e positivos ou zero.');return n;}
function textValue(d,k){const v=String(d.get(k)||'').trim();if(!v||v.length>100)throw Error('Preencha o nome ou a descrição (até 100 caracteres).');return v;}
function selectField(label,name,options,value,full=false){return '<label class="field '+(full?'full':'')+'">'+label+'<select name="'+name+'">'+options.map(([k,l])=>'<option value="'+k+'" '+(k===value?'selected':'')+'>'+l+'</option>').join('')+'</select></label>';}
function recordForm(id=null,kind='in',status='paid',quote=null){
 const r=state.records.find(x=>x.id===id)||{kind,status,title:quote?.name||'',amount:quote?.price||0,date:F.date(),cat:kind==='in'?'Serviços':'Outros'};
 modal(id?'Editar lançamento':'Novo lançamento','<div class="fields">'+selectField('Movimento','kind',[['in','Entrada de dinheiro'],['out','Saída de dinheiro']],r.kind)+selectField('Situação','status',[['paid','Já recebido / pago'],['pending','A receber / a pagar']],r.status)+field('Descrição','title',r.title,'text','',true)+field('Valor · R$','amount',r.amount)+field('Data / vencimento','date',r.date,'date')+selectField('Categoria','cat',['Serviços','Vendas','Materiais','Fornecedores','Estrutura','Equipe','Impostos','Pró-labore','Outros'].map(x=>[x,x]),r.cat,true)+'</div><p class="fineprint">Para parcelas, registre cada parcela com seu vencimento. Uma conta pendente só altera o caixa quando você marcar como recebida ou paga.</p>');
 $('#modal-form').onsubmit=e=>{e.preventDefault();try{
 const d=new FormData(e.target),amount=numeric(d,'amount');if(amount<=0)throw Error('O valor precisa ser maior que zero.');
 const selectedDate=d.get('date');if(d.get('status')==='paid'&&selectedDate>F.date())throw Error('Para uma data futura, escolha “A receber / a pagar”.');
 const next={id:id||F.uid(),kind:d.get('kind'),status:d.get('status'),title:textValue(d,'title'),amount:F.round(amount),date:selectedDate,cat:d.get('cat')};
 if(id&&r.paidDate&&next.status==='paid')next.paidDate=r.paidDate;
 if(id&&r.status==='pending'&&next.status==='paid')next.paidDate=F.date();
 const test={...state,records:[...state.records.filter(x=>x.id!==id),next]};F.validate(test);state.records=test.records;
 if(quote){quote.recordId=next.id;}
 save();closeModal();render();toast('Lançamento salvo.');
 }catch(err){formError(err);}};
}
